import {DatasetContext,inputLabel} from './DatasetContext';
import {useEffect,useRef,useState} from 'react';
import type {FormEvent,ReactNode} from 'react';
import {api,post} from './api';
import {Candles,Equity} from './Charts';
import {Benchmarks} from './Benchmarks';
import {RandomControls} from './RandomControls';
import {Behavior} from './Behavior';
import {Ablations} from './Ablations';
import {BorrowSensitivity} from './BorrowSensitivity';
import {StudyUnit,StudyContext} from './StudyFlow';
import {SearchSamplingInputs,SearchSamplingResults,defaultSampling} from './SearchSampling';
import {SearchStatisticsInputs,SearchStatisticsResults,defaultStatisticsDraft,statisticsPolicy} from './SearchStatistics';
import {SavedJobHistory} from './SavedPages';
import {TrialLedger} from './TrialLedger';
import {SpreadFlow} from './SpreadFlow';
import {TradeTwins,StartTradeTwins} from './TradeTwins';
